function restartLong(){
  try { window.Breakfast.dispose(); } catch (e) {}
  window.Breakfast.start(document.getElementById("bfGameHost"),
    { target:{ id:"su", name:"苏晚晴", bond:40 }, duration:999, goal:99, onFinish:function(){} });
